const SITES={"type":"FeatureCollection","features":[{"type":"Feature","geometry":{"type":"Point","coordinates":[-83.1222,38.3739]},"properties":{"slug":"carter-caves-state-resort-park","name":"Carter Caves State Resort Park","state":"KY","summary":"A 1,820-acre Kentucky state resort park on karst whose Saltpeter Cave was an industrial niter mine during the War of 1812 before it became a tourist cave.","acreage":"1,820","geology":"~330 to 323 Mya Mississippian Slade Formation limestone, about 25 m thick, in which the caves formed, Saltpeter Cave along a bedding plane near the top of the Slade; the ridgetops are capped by the Upper Mississippian Carter Caves Sandstone at the base of the Paragon Formation, the caprock of the karst system, in a fluviokarst of deeply incised valleys covering 106 km2. Arches form in both rocks: Fern Bridge and Cascade Bridge are joint-controlled alcove arches in the Carter Caves Sandstone, and an arch in the park's Slade limestone is 193 feet (59 m) wide, the widest measured in Kentucky. Proglacial Lake Tight backflooded the valleys to the 275 m contour for some 10,000 years in the mid-Pleistocene, about 0.77 Mya, and its shorelines helped cut the sandstone arches.","epoch":"Middle to Late Mississippian (Slade Formation; Carter Caves Sandstone of the Paragon Formation)","agency":"Kentucky Department of Parks","agency_type":"State park","nations":["Shawnee","Cherokee","Lenape (Delaware)","Haudenosaunee"],"cultures":["Fort Ancient culture"],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-83.4308,39.0264]},"properties":{"slug":"serpent-mound","name":"Serpent Mound","state":"OH","summary":"A 60-acre Ohio History Connection memorial holding the Serpent Mound effigy, preserved because Frederic Ward Putnam bought it in 1886 to excavate it.","acreage":"60","geology":"~433 to 427 Mya Silurian Peebles Dolomite with the underlying Lilley and Bisher Formations, bluish gray, thick to massive bedded, vuggy to cavernous, up to 120 feet thick and a cliff former; the plateau sits on the southwestern part of the Serpent Mound impact structure, a crater about 14 km (8.7 miles) across formed 252 to 330 Mya, in which the surrounding Paleozoic beds were uplifted, dropped, faulted, and folded. The site lies in unglaciated Ohio.","epoch":"Silurian (Peebles Dolomite); late Paleozoic impact structure","agency":"Ohio History Connection","agency_type":"State historic site","nations":["Shawnee","Myaamia (Miami)"],"cultures":["Adena","Fort Ancient culture"],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-85.6332,38.4247]},"properties":{"slug":"charlestown-state-park","name":"Charlestown State Park","state":"IN","summary":"A 4,048-acre Indiana state park on the riverfront of what was the world's largest smokeless powder plant, on land the federal government took from farm families in 1940 and 1941.","acreage":"4,048","geology":"~394 to 384 Mya Middle Devonian Muscatatuck Group limestone and dolomite on the plateau, with the Silurian Louisville Limestone below it exposed in the Fourteenmile Creek bluffs; Devonian fossil outcrops and karst sinkholes along the trails, and a colluvial lag of Illinoian till erratics on the slopes.","epoch":"Middle Devonian (Muscatatuck Group); Silurian (Louisville Limestone)","agency":"Indiana Department of Natural Resources, Division of State Parks","agency_type":"State park","nations":["Shawnee","Myaamia (Miami)","Lenape (Delaware)"],"cultures":[],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-86.539,38.2774]},"properties":{"slug":"hemlock-cliffs","name":"Hemlock Cliffs","state":"IN","summary":"A box canyon under remnant hemlock in the Hoosier National Forest, in Crawford County, where by the Forest Service's own regional history an unwritten law barred Black people from the county.","acreage":"1,860","geology":"~328 to 324 Mya Late Mississippian (Chesterian) Buffalo Wallow Group, mostly sandstone and shale with thin micritic limestone; the box canyon walls are sandstone, described in Forest Service and geological guide material as Tar Springs sandstone over the Glen Dean Limestone, and weather into rockshelters and overhangs.","epoch":"Late Mississippian (Chesterian)","agency":"USDA Forest Service (Hoosier National Forest, Tell City Ranger District)","agency_type":"USFS","nations":["Piankeshaw","Lenape (Delaware)","Shawnee","Myaamia (Miami)","Kickapoo"],"cultures":["Paleoindian"],"primary_nation":"Piankeshaw"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-86.5222,38.623]},"properties":{"slug":"wesley-chapel-gulf","name":"Wesley Chapel Gulf","state":"IN","summary":"A 188-acre karst gulf in the Hoosier National Forest, in Orange County, where in June 1902 the New York Times reported White Cap notices posted in a campaign to expel the county's Black residents.","acreage":"188","geology":"~341 to 334 Mya Middle Mississippian Blue River Group, mostly micritic, skeletal, and oolitic limestone of the Mitchell Plateau karst belt; the gulf is an 8.3-acre collapse sink where the rock roof over an underground channel of the Lost River fell in, leaving a box canyon with bedrock walls 30 to 100 feet high.","epoch":"Middle Mississippian (Blue River Group)","agency":"USDA Forest Service (Hoosier National Forest, Brownstown Ranger District)","agency_type":"USFS","nations":["Myaamia (Miami)","Shawnee","Lenape (Delaware)","Kickapoo","Piankeshaw","Kaskaskia"],"cultures":[],"primary_nation":"Myaamia (Miami)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-86.42,38.7333]},"properties":{"slug":"spring-mill-state-park","name":"Spring Mill State Park","state":"IN","summary":"A 1,358-acre Indiana state park with 145 acres of old-growth forest, much of it built from 1933 to 1941 by Civilian Conservation Corps companies in segregated camps.","acreage":"1,358","geology":"~340 Mya Middle Mississippian St. Louis Limestone of the Blue River Group, horizontally bedded skeletal grainstone to wackestone with chert nodules, capped by terra rossa red clay; the park lies on the Mitchell Karst Plain, where sinkholes exceed 1,000 per square mile and the limestone holds Twin, Bronson, Donaldson, and Hamer caves.","epoch":"Middle Mississippian (Blue River Group)","agency":"Indiana Department of Natural Resources, Division of State Parks","agency_type":"State park","nations":["Lenape (Delaware)","Potawatomi","Myaamia (Miami)","Shawnee","Kickapoo","Kaskaskia"],"cultures":[],"primary_nation":"Lenape (Delaware)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-84.0903,39.4078]},"properties":{"slug":"fort-ancient-earthworks","name":"Fort Ancient Earthworks and Nature Preserve","state":"OH","summary":"A 764-acre Ohio History Connection earthwork and nature preserve whose mounds and stone graves were dug in the late 1880s, before the site was protected.","acreage":"764","geology":"~453 to 444 Mya Late Ordovician Waynesville and Arnheim Formations, interbedded gray to bluish gray shale and limestone 140 to 220 feet thick, capped on the plateau by glacial till; the Little Miami has cut 270 feet below the rim, and the builders used the local surface limestone for the stone-capped mounds and pavements.","epoch":"Late Ordovician (Cincinnatian Series, Richmondian)","agency":"Ohio History Connection (operated by the Dayton Society of Natural History)","agency_type":"State historic site","nations":["Shawnee","Myaamia (Miami)"],"cultures":["Hopewell","Fort Ancient culture"],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-84.2809,39.6276]},"properties":{"slug":"miamisburg-mound","name":"Miamisburg Mound","state":"OH","summary":"A 37-acre park around the Miamisburg Mound, which gave its name to Mound Laboratory, the Atomic Energy Commission plant sited beside it in 1946 to continue the Dayton Project's extraction of polonium-210.","acreage":"37","geology":"~448 to 446 Mya Late Ordovician Drakes, Whitewater, and Liberty Formations, interbedded gray limestone and shale 60 to 150 feet thick, buried here under glacial till; the mound stands on a till-capped bluff about 100 feet above the Great Miami, whose valley is a preglacial channel filled with Wisconsinan sand and gravel.","epoch":"Late Ordovician (Cincinnatian Series, Richmondian); Pleistocene till and buried valley fill","agency":"Ohio History Connection (maintained by the City of Miamisburg)","agency_type":"State historic site","nations":["Myaamia (Miami)","Shawnee"],"cultures":["Adena"],"primary_nation":"Myaamia (Miami)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-84.0135,39.5756]},"properties":{"slug":"spring-valley-wildlife-area","name":"Spring Valley Wildlife Area","state":"OH","summary":"An 842-acre Ohio wildlife area whose lake and marsh, offered as a specimen of the state's vanishing wetlands, is the flooded ground of a commercial fur farm.","acreage":"842","geology":"~450 to 449 Mya Late Ordovician Grant Lake and Fairview Formations with the Miamitown Shale, limestone and shale in roughly equal proportion, gray to bluish gray and fossiliferous, planar to nodular bedded; overlain in the valley by Wisconsinan outwash sand and gravel.","epoch":"Late Ordovician (Cincinnatian Series, Maysvillian); Wisconsinan valley fill","agency":"Ohio DNR Division of Wildlife","agency_type":"State wildlife area","nations":["Shawnee","Myaamia (Miami)"],"cultures":["Adena","Hopewell"],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-84.0658,39.8033]},"properties":{"slug":"huffman-prairie-flying-field","name":"Huffman Prairie Flying Field","state":"OH","summary":"An 84-acre flying field holding one of Ohio's largest tallgrass prairie remnants, which survives because the land around it was taken first for flood control and then for the military.","acreage":"84","geology":"~453 to 444 Mya Late Ordovician Waynesville and Arnheim Formations, interbedded shale and limestone, buried here beneath the Mad River's Wisconsinan valley fill of sand and gravel; the field's own ground is Linwood muck over Westland silty clay loam, a wet prairie soil poorly suited to row crops, which is why it stayed in pasture.","epoch":"Late Ordovician (Cincinnatian Series, Richmondian) bedrock; Wisconsinan to Holocene buried valley fill","agency":"National Park Service (Dayton Aviation Heritage National Historical Park), on Wright-Patterson Air Force Base land","agency_type":"NPS","nations":["Shawnee","Myaamia (Miami)"],"cultures":[],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-84.4924,39.2016]},"properties":{"slug":"caldwell-nature-preserve","name":"Caldwell Nature Preserve","state":"OH","summary":"A 123-acre Cincinnati preserve of old growth forest whose ravines drain to Mill Creek, named the most endangered urban river in the country in 1996.","acreage":"123","geology":"~450 Mya Late Ordovician Kope Formation, 75 percent gray to bluish gray shale interbedded with 25 percent thin limestone, 200 to 260 feet thick; the blue-gray clay shale is exposed directly in the preserve's creek beds where the ravines cut east toward Mill Creek.","epoch":"Late Ordovician (Cincinnatian Series, Edenian)","agency":"Cincinnati Parks","agency_type":"Municipal park","nations":["Shawnee","Myaamia (Miami)"],"cultures":[],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-88.6561,37.5186]},"properties":{"slug":"bell-smith-springs","name":"Bell Smith Springs Recreation Area","state":"IL","summary":"A 1,300-acre sandstone canyon recreation area in the Shawnee National Forest, a forest assembled after 1933 from worn-out Depression-era farms bought from Pope County families.","acreage":"1,300","geology":"~318 Mya Early Pennsylvanian (Morrowan) Caseyville Formation sandstone, cut into the box canyon, natural bridge, and Devil's Backbone by Bay Creek tributaries; the oldest Pennsylvanian rock exposed in the Illinois Basin.","epoch":"Early Pennsylvanian (Morrowan)","agency":"USDA Forest Service (Shawnee National Forest, Hidden Springs Ranger District)","agency_type":"USFS","nations":["Kaskaskia","Myaamia (Miami)","Kickapoo"],"cultures":[],"primary_nation":"Kaskaskia"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-87.9333,37.8167]},"properties":{"slug":"hovey-lake-fish-and-wildlife-area","name":"Hovey Lake Fish and Wildlife Area","state":"IN","summary":"A 7,404-acre Indiana fish and wildlife area of cypress swamp and bottomland forest in Posey County, the center of two notorious cases of looting at Native American archaeological sites in the late 1980s.","acreage":"7,404","geology":"~300 Mya Pennsylvanian bedrock (Shelburn, Patoka, and Bond Formations) buried beneath Wisconsinan-to-Holocene Ohio River alluvium; the lake itself an oxbow cut into the valley-fill sand, gravel, and silt.","epoch":"Pennsylvanian bedrock; Late Pleistocene to Holocene surficial deposits","agency":"Indiana Department of Natural Resources, Division of Fish and Wildlife","agency_type":"State fish and wildlife area","nations":["Myaamia (Miami)","Piankeshaw","Shawnee"],"cultures":[],"primary_nation":"Myaamia (Miami)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-85.7636,38.2756]},"properties":{"slug":"falls-of-the-ohio-state-park","name":"Falls of the Ohio State Park","state":"IN","summary":"A 165-acre Indiana state park at the falls of the Ohio River, beside Shippingport, a river town cut off into an island and emptied by the canal built to bypass the falls.","acreage":"165","geology":"~390 Mya Middle Devonian Jeffersonville Limestone, a 35-foot sequence exposing one of North America's largest and most accessible Devonian fossil coral beds.","epoch":"Middle Devonian","agency":"Indiana Department of Natural Resources, Division of State Parks","agency_type":"State park","nations":["Shawnee","Myaamia (Miami)","Haudenosaunee","Lenape (Delaware)"],"cultures":[],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-88.1558,37.4686]},"properties":{"slug":"cave-in-rock-state-park","name":"Cave-in-Rock State Park","state":"IL","summary":"A 204-acre Illinois state park on the Ohio River bluffs around a cave that was a station on the Reverse Underground Railroad.","acreage":"204","geology":"~335 Mya Mississippian (Meramecian) St. Louis Limestone, the cavern itself dissolved from the formation in the Ohio River bluff.","epoch":"Mississippian (Meramecian)","agency":"Illinois Department of Natural Resources","agency_type":"State park","nations":["Kaskaskia","Shawnee","Kickapoo"],"cultures":[],"primary_nation":"Kaskaskia"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-85.1542,38.6706]},"properties":{"slug":"general-butler-state-resort-park","name":"General Butler State Resort Park","state":"KY","summary":"A 791-acre Kentucky resort park laid over the Butler family plantation, worked by enslaved people across three generations, whose dead lie unnamed on the grounds.","acreage":"791","geology":"~450 Mya Upper Ordovician (Cincinnatian) Kope Formation, calcareous shale interbedded with thin fossiliferous limestone lenses bearing brachiopods, bryozoans, and trilobites from the shallow tropical sea that covered the region, exposed in the bluffs above the Ohio and Kentucky rivers; the park's ridgetops rise to about 705 feet over the buried preglacial Old Kentucky River channel, whose northeastward course past Carrollton was diverted to the present Ohio River valley by Pleistocene glaciation.","epoch":"Late Ordovician (Cincinnatian)","agency":"Kentucky Department of Parks","agency_type":"State park","nations":["Shawnee","Cherokee","Myaamia (Miami)"],"cultures":[],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-85.39,39.005]},"properties":{"slug":"big-oaks-national-wildlife-refuge","name":"Big Oaks National Wildlife Refuge","state":"IN","summary":"A 50,000-acre refuge on the former Jefferson Proving Ground, where the Army cleared a farming community in 1940 and test-fired more than 24 million rounds of ordnance until 1995.","acreage":"50,000","geology":"~445 Mya Upper Ordovician (Cincinnatian) limestone and shale bedrock, mantled by Illinoian glacial till that forms the flat, poorly drained flatwoods plain of the Muscatatuck Regional Slope (~150,000 years).","epoch":"Late Ordovician (Cincinnatian) bedrock beneath Pleistocene (Illinoian) till","agency":"U.S. Fish and Wildlife Service (land owned by the U.S. Army; ~1,000-acre inholding managed by the Indiana Air National Guard)","agency_type":"USFWS","nations":["Myaamia (Miami)","Wea","Shawnee"],"cultures":[],"primary_nation":"Myaamia (Miami)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-85.2155,39.0614]},"properties":{"slug":"versailles-state-park","name":"Versailles State Park","state":"IN","summary":"A 5,988-acre Indiana state park built from 1934 by buying out struggling farm families along Laughery Creek under the New Deal's submarginal-land program.","acreage":"5,988","geology":"~445 Mya Upper Ordovician (Cincinnatian) Dillsboro Formation, interbedded fossiliferous limestone and shale exposed on the lower slopes and in the Laughery Creek valley, rich in brachiopods, bryozoans, and crinoids from the shallow tropical sea that covered the region.","epoch":"Late Ordovician (Cincinnatian)","agency":"Indiana Department of Natural Resources, Division of State Parks","agency_type":"State park","nations":["Myaamia (Miami)","Wea","Shawnee"],"cultures":[],"primary_nation":"Myaamia (Miami)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-83.4914,38.0814]},"properties":{"slug":"cave-run-lake","name":"Cave Run Lake","state":"KY","summary":"An 8,270-acre Army Corps of Engineers reservoir in the Daniel Boone National Forest west of Morehead, begun in 1965 and filled by 1974.","acreage":"8,270","geology":"~345 Mya Mississippian Borden Formation (Early Osagean siltstone, shale, and marine ammonoid-bearing beds) exposed in the valley floors, capped on the Pottsville Escarpment ridgetops by resistant Early Pennsylvanian Lee Formation quartz sandstone (~320 Mya); the Licking River here cuts the escarpment margin where the Cumberland Plateau meets the Outer Bluegrass.","epoch":"Early Mississippian (Osagean) to Early Pennsylvanian (Morrowan).","agency":"U.S. Army Corps of Engineers (Louisville District); recreation managed by USDA Forest Service (Daniel Boone National Forest, Cumberland Ranger District)","agency_type":"USACE reservoir","nations":["Shawnee","Cherokee"],"cultures":["Adena","Fort Ancient culture","Paleoindian"],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-86.5111,43.6786]},"properties":{"slug":"silver-lake-state-park","name":"Silver Lake State Park","state":"MI","summary":"A 2,936-acre Michigan state park of open Lake Michigan dunes in Oceana County, where the Grand River Odawa were resettled and then lost their 1855 treaty allotments within a generation.","acreage":"2,936","geology":"Holocene aeolian dune sand (dune building began about 5,500 calibrated years ago at the Nipissing high stand, roughly 75 percent of it between about 4,000 and 2,500 years ago) over Late Pleistocene glacial and glaciolacustrine sand deposited in the Lake Michigan basin (~14,000 years)","epoch":"Holocene (dune sand) over Late Pleistocene (Wisconsin glaciation)","agency":"Michigan Department of Natural Resources, Parks and Recreation Division","agency_type":"State park","nations":["Ottawa (Odawa)","Ojibwe","Potawatomi"],"cultures":[],"primary_nation":"Ottawa (Odawa)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-86.202,42.7059]},"properties":{"slug":"saugatuck-dunes-state-park","name":"Saugatuck Dunes State Park","state":"MI","summary":"A 1,000-acre Lake Michigan dune park whose wooded ridge held an Augustinian seminary from 1949 to 1977 and then a minimum-security state prison.","acreage":"1,000","geology":"Holocene aeolian dune sand (the high perched dunes largely post-Nipissing, roughly 4,500 years old) over Late Pleistocene glaciolacustrine sand and gravel laid down in Glacial Lake Chicago (~14,000 years)","epoch":"Holocene (dune sand) over Late Pleistocene (Wisconsin glaciation)","agency":"Michigan Department of Natural Resources, Parks and Recreation Division","agency_type":"State park","nations":["Ottawa (Odawa)","Potawatomi","Ojibwe"],"cultures":[],"primary_nation":"Ottawa (Odawa)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-86.274,43.129]},"properties":{"slug":"pj-hoffmaster-state-park","name":"P.J. Hoffmaster State Park","state":"MI","summary":"A 1,200-acre Lake Michigan dune park in a coastal dune belt that was among the most heavily strip-mined in Michigan for automotive foundry sand.","acreage":"1,200","geology":"Holocene aeolian dune sand (transgressive parabolic dunes most active since the mid-Holocene Nipissing transgression roughly 5,500 years ago, with a back-dune ridge dated to about 7,200 years) over Late Pleistocene glaciolacustrine sand of Glacial Lake Chicago (~14,000 years)","epoch":"Holocene (dune sand) over Late Pleistocene (Wisconsin glaciation)","agency":"Michigan Department of Natural Resources, Parks and Recreation Division","agency_type":"State park","nations":["Ottawa (Odawa)","Ojibwe","Potawatomi"],"cultures":[],"primary_nation":"Ottawa (Odawa)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-86.59,41.906]},"properties":{"slug":"warren-dunes-state-park","name":"Warren Dunes State Park","state":"MI","summary":"A 1,952-acre Lake Michigan dune park whose dune system was strip-mined for foundry sand as recently as the 1970s.","acreage":"1,952","geology":"Holocene aeolian dune sand (the high dunes largely post-Nipissing, roughly 6,000 to 4,000 years old) over Late Pleistocene glacial and glaciolacustrine deposits on the abandoned bed of Glacial Lake Chicago (~14,000 years)","epoch":"Holocene (dune sand) over Late Pleistocene (Wisconsin glaciation)","agency":"Michigan Department of Natural Resources, Parks and Recreation Division","agency_type":"State park","nations":["Potawatomi","Ottawa (Odawa)","Ojibwe"],"cultures":[],"primary_nation":"Potawatomi"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-85.3806,41.3331]},"properties":{"slug":"chain-o-lakes-state-park","name":"Chain O'Lakes State Park","state":"IN","summary":"A 2,718-acre Indiana state park of glacial lakes, dedicated in 1960 after the farms, homes, and cottages around the lakes were bought out and torn down.","acreage":"2,718","geology":"Late Pleistocene Wisconsin-age glacial deposits (kettle lakes, eskers, and kames left by the Saginaw and Erie glacial lobes, ~13,000 to 14,000 years) over ~370 Mya Upper Devonian Antrim Shale bedrock buried beneath as much as 360 feet of glacial drift","epoch":"Late Pleistocene (Wisconsin glaciation)","agency":"Indiana DNR","agency_type":"State park","nations":["Potawatomi","Myaamia (Miami)"],"cultures":[],"primary_nation":"Potawatomi"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-85.2317,41.0333]},"properties":{"slug":"eagle-marsh-nature-preserve","name":"Eagle Marsh Nature Preserve","state":"IN","summary":"An 831-acre restored wetland on a remnant of the Great Marsh of the Little River, a Miami and Potawatomi hunting ground ditched and drained for farmland between the 1870s and 1888.","acreage":"831","geology":"Late Pleistocene Wisconsin-age glacial deposits (Fort Wayne Moraine and Maumee lake plain, ~14,000 years) over ~370 Mya Upper Devonian Antrim Shale bedrock","epoch":"Late Pleistocene (Wisconsin glaciation)","agency":"Little River Wetlands Project (nonprofit land trust)","agency_type":"Private preserve","nations":["Myaamia (Miami)","Potawatomi"],"cultures":[],"primary_nation":"Myaamia (Miami)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-83.5365,35.6857]},"properties":{"slug":"great-smoky-mountains-national-park","name":"Great Smoky Mountains National Park","state":"TN","summary":"A 522,427-acre national park, about 95 percent forested, created after industrial logging that began in 1901 had clear-cut much of the land.","acreage":"522,427","geology":"~800-700 Mya Neoproterozoic metasedimentary rock (Ocoee Supergroup: Snowbird, Great Smoky, and Walden Creek Groups)","epoch":"Neoproterozoic","agency":"National Park Service","agency_type":"NPS","nations":["Cherokee"],"cultures":[],"primary_nation":"Cherokee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-83.5604,35.1804]},"properties":{"slug":"nantahala-national-forest","name":"Nantahala National Forest","state":"NC","summary":"A 531,148-acre national forest in the southern Appalachians bordering Fontana Lake, whose dam, completed in 1944, displaced 1,311 families and relocated 1,047 graves.","acreage":"531,148","geology":"~1,100 to 440 Mya Late Proterozoic to Middle Ordovician metasedimentary rock (Nantahala Formation siltstone/sandstone, Brasstown Formation schist)","epoch":"Late Proterozoic to Middle Ordovician","agency":"USDA Forest Service (National Forests in North Carolina)","agency_type":"USFS","nations":["Cherokee"],"cultures":[],"primary_nation":"Cherokee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-83.9357,34.7372]},"properties":{"slug":"blood-mountain-wilderness","name":"Blood Mountain Wilderness","state":"GA","summary":"A 7,800-acre Georgia wilderness on land that was industrially logged before the Forest Service bought it in 1911, in its first Weeks Act purchase in the state.","acreage":"7,800","geology":"~700 Mya Neoproterozoic metasedimentary rock over ~1,000 Mya Grenville-age gneiss basement (Blue Ridge Province)","epoch":"Neoproterozoic","agency":"USDA Forest Service (Chattahoochee-Oconee National Forests)","agency_type":"USFS","nations":["Cherokee"],"cultures":[],"primary_nation":"Cherokee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-83.9153,34.7066]},"properties":{"slug":"chattahoochee-national-forest","name":"Chattahoochee National Forest","state":"GA","summary":"A 751,069-acre national forest in Georgia's southern Appalachians, where sediments near former Dahlonega Gold Belt mines still carry mercury from historic mining.","acreage":"751,069","geology":"~1,000 to 460 Mya Neoproterozoic to Ordovician metasedimentary rock (Tallulah Falls Formation, Coweeta Group)","epoch":"Neoproterozoic to Early Paleozoic","agency":"USDA Forest Service (Chattahoochee-Oconee National Forests)","agency_type":"USFS","nations":["Cherokee"],"cultures":[],"primary_nation":"Cherokee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-83.6022,32.8382]},"properties":{"slug":"ocmulgee-mounds-national-historical-park","name":"Ocmulgee Mounds National Historical Park","state":"GA","summary":"A 3,336-acre national historical park on the Ocmulgee River, where from 1933 to 1941 more than 800 relief workers carried out the largest archaeological dig in the country to that point.","acreage":"3,336","geology":"~85 Mya Late Cretaceous Ripley Formation clay and sand bedrock at the Fall Line, with Eocene and Pliocene to Holocene alluvium also present nearby","epoch":"Late Cretaceous","agency":"National Park Service","agency_type":"NPS","nations":["Muscogee (Creek)","Hitchiti"],"cultures":[],"primary_nation":"Muscogee (Creek)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-84.0205,33.1783]},"properties":{"slug":"high-falls-state-park","name":"High Falls State Park","state":"GA","summary":"A 1,050-acre Georgia state park on the Towaliga River whose mill village stood inside a slave economy: in 1860 enslaved people were close to two thirds of Monroe County's population.","acreage":"1,050","geology":"~300 Mya Pennsylvanian igneous intrusion (High Falls Granite, Cedar Rock Complex), Piedmont crystalline rock exposed at the fall line","epoch":"Pennsylvanian (Alleghanian orogeny)","agency":"Georgia Department of Natural Resources, State Parks Division","agency_type":"State park","nations":["Muscogee (Creek)","Hitchiti"],"cultures":[],"primary_nation":"Muscogee (Creek)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-82.4179,32.5989]},"properties":{"slug":"ohoopee-dunes-wildlife-management-area","name":"Ohoopee Dunes Wildlife Management Area","state":"GA","summary":"A 9,271-acre Georgia wildlife management area of sandhill scrub, home of the endemic Georgia plume, on dunes whose longleaf pine was cut by sawmills and turpentine operators from the 1870s through the 1960s.","acreage":"9,271","geology":"~30,000 to 15,000 years ago Late Pleistocene eolian quartz sand, deposited as parabolic dunes reworked by wind from Ohoopee River braid-plain sediments during repeated Wisconsin-glaciation flood cycles","epoch":"Late Pleistocene (Wisconsin Glaciation)","agency":"Georgia Department of Natural Resources, Wildlife Resources Division","agency_type":"State wildlife management area","nations":["Yuchi","Muscogee (Creek)"],"cultures":[],"primary_nation":"Yuchi"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-80.7643,32.2494]},"properties":{"slug":"pinckney-island-national-wildlife-refuge","name":"Pinckney Island National Wildlife Refuge","state":"SC","summary":"A 4,053-acre refuge of maritime forest and salt marsh on a former plantation island, where headstones mark United States Colored Troops recruited from its newly freed people.","acreage":"4,053","geology":"~130,000 to 80,000 years ago Late Pleistocene barrier and back-barrier sands of the Wando Formation (equivalent to the Princess Anne and Pamlico terraces), laid down as fluctuating interglacial sea levels built and reworked the string of sea islands around Port Royal Sound","epoch":"Late Pleistocene (Wando Formation, Princess Anne/Pamlico terraces)","agency":"U.S. Fish and Wildlife Service (Savannah Coastal Refuges Complex)","agency_type":"USFWS","nations":["Cusabo (Escamacu)","Yamasee"],"cultures":[],"primary_nation":"Cusabo (Escamacu)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-97.2734,37.7287]},"properties":{"slug":"chisholm-creek-park","name":"Chisholm Creek Park","state":"KS","summary":"A 282-acre Wichita park of restored prairie and wetland on a creek that also drains the city's industrial north side and some of the largest groundwater contamination sites in Kansas.","acreage":"282","geology":"~285 to 275 Mya Early Permian gray and blue-gray calcareous shale of the Wellington Formation and the overlying reddish-brown Ninnescah Shale (Sumner Group), laid down in a shrinking, evaporating arm of the Permian sea near the margin of the Hutchinson salt basin; the shales hold thin beds of impure limestone, gypsum, and anhydrite that record an arid climate","epoch":"Early Permian (Leonardian)","agency":"City of Wichita Park and Recreation (Great Plains Nature Center cooperative with USFWS and Kansas Department of Wildlife and Parks)","agency_type":"Municipal park","nations":["Wichita","Osage","Comanche","Kiowa"],"cultures":[],"primary_nation":"Wichita"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-104.8404,37.61]},"properties":{"slug":"lathrop-state-park","name":"Lathrop State Park","state":"CO","summary":"A 1,451-acre Colorado state park in the Huerfano County coalfield, bounded by a ridge named for Fred Walsen, who opened the county's first commercial coal mine in 1876.","acreage":"1,451","geology":"~24 to 23 Mya Late Oligocene igneous intrusions of the Spanish Peaks system, whose two shallow stocks (West Spanish Peak quartz syenite, about 24.6 Ma; East Spanish Peak granodiorite, about 23.4 Ma) cracked the surrounding crust into a radial swarm of more than 400 dikes reaching 25 miles outward; one of these, the Walsen Ridge dike, forms a hard volcanic wall along the park's northern boundary, left standing where erosion stripped the softer Eocene Cuchara Formation sandstones it cut through","epoch":"Late Oligocene (Spanish Peaks intrusions) / Eocene (Cuchara Formation country rock)","agency":"Colorado Parks and Wildlife","agency_type":"State park","nations":["Mouache Ute (Núuchi-u)","Jicarilla Apache (Tinde)","Comanche","Kiowa","Cheyenne","Arapaho","Ute (Núuchi-u / Núu-agha-tʉvʉ-pʉ̱)"],"cultures":[],"primary_nation":"Mouache Ute (Núuchi-u)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-108.473,37.1675]},"properties":{"slug":"mesa-verde-national-park","name":"Mesa Verde National Park","state":"CO","summary":"A 52,485-acre national park of cliff dwellings whose story of scientific discovery rests on the excavation of graves, including some twenty opened by Gustaf Nordenskiöld in 1891.","acreage":"52,485","geology":"~80-75 Mya Late Cretaceous Cliff House Sandstone (Mesaverde Group), a pale yellow-orange, cliff-forming, cross-bedded marine sandstone roughly 400 feet thick, deposited in a shallow near-shore sea during a northward transgression; it caps the softer Menefee Formation and the underlying Mancos Shale, and where the massive sandstone overlies the erodible shale it weathers into the deep alcoves that shelter the cliff dwellings","epoch":"Late Cretaceous (Campanian)","agency":"National Park Service","agency_type":"NPS","nations":["Hopi","Zuni (A:shiwi)","Pueblos","Ute Mountain Ute","Navajo (Diné)","Ute (Núuchi-u / Núu-agha-tʉvʉ-pʉ̱)"],"cultures":["Ancestral Puebloan"],"primary_nation":"Hopi"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-109.6325,37.5221]},"properties":{"slug":"bears-ears-national-monument","name":"Bears Ears National Monument","state":"UT","summary":"A 1.36 million-acre national monument co-managed with the Bears Ears Commission, whose Cedar Mesa has a long history of archaeological extraction and grave robbing.","acreage":"1,360,000","geology":"~290-270 Mya Early Permian Cedar Mesa Sandstone (Cutler Group), a wind- and shoreline-deposited sandstone that forms the slickrock of Comb Ridge and the Cedar Mesa canyons; the strata were later buckled into the Comb Ridge monocline, a roughly 80-mile fold raised during the Laramide orogeny about 70 to 50 million years ago, whose west-facing teeth shed the washes that hold the cliff dwellings","epoch":"Early Permian (Cedar Mesa Sandstone)","agency":"Bureau of Land Management and USDA Forest Service (co-managed with the Bears Ears Commission)","agency_type":"National monument","nations":["Hopi","Navajo (Diné)","Ute Mountain Ute","Ute Indian Tribe","Zuni (A:shiwi)","Pueblos","Ute (Núuchi-u / Núu-agha-tʉvʉ-pʉ̱)"],"cultures":["Ancestral Puebloan"],"primary_nation":"Hopi"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-109.54,38.7281]},"properties":{"slug":"arches-national-park","name":"Arches National Park","state":"UT","summary":"A 76,679-acre national park of sandstone arches, about one mile from the site of the Atlas uranium mill, which processed ore for the Atomic Energy Commission from 1956 to 1984.","acreage":"76,679","geology":"~165-145 Mya Middle to Late Jurassic Entrada Sandstone (Slick Rock Member), the wind-deposited desert sandstone in which nearly all the arches are cut; the park's structure rests on a ~300 Mya Pennsylvanian salt bed (Paradox Formation) whose slow flow and collapse buckled the overlying rock into the fins that erode into arches","epoch":"Middle to Late Jurassic (Entrada Sandstone) / Pennsylvanian (Paradox salt)","agency":"National Park Service","agency_type":"NPS","nations":["Ute (Núuchi-u / Núu-agha-tʉvʉ-pʉ̱)","Sheberetch (Seuvarits) Ute"],"cultures":["Fremont","Ancestral Puebloan"],"primary_nation":"Ute (Núuchi-u / Núu-agha-tʉvʉ-pʉ̱)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-112.1677,37.6283]},"properties":{"slug":"bryce-canyon-national-park","name":"Bryce Canyon National Park","state":"UT","summary":"A 35,835-acre national park on the Paunsaugunt rim, in a region whose Paiute descendants were devastated by the federal termination act of 1954.","acreage":"35,835","geology":"~50-40 Mya Eocene Claron Formation: silty limestone, siltstone, dolomite, and mudstone deposited in Paleocene-Eocene lakes; the iron- and manganese-tinted pink and white members erode into the park's hoodoos","epoch":"Eocene (Claron Formation)","agency":"National Park Service","agency_type":"NPS","nations":["Southern Paiute (Nuwuvi)","Kaibab Band of Paiute Indians"],"cultures":["Fremont","Ancestral Puebloan"],"primary_nation":"Southern Paiute (Nuwuvi)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-110.5,44.6]},"properties":{"slug":"yellowstone-national-park","name":"Yellowstone National Park","state":"WY","summary":"A 2.2 million-acre national park that became the template for fortress conservation, the making of protected wilderness by removing its Indigenous inhabitants.","acreage":"2,219,791","geology":"~2.8 billion years (Archean) gneiss and granitoid basement exposed in the northern park (Hellroaring and Crevice plutons near the Montana boundary); overlain by Quaternary rhyolitic caldera volcanism, the Lava Creek eruption forming the present Yellowstone Caldera ~631,000 years ago","epoch":"Archean (basement) / Quaternary (Yellowstone Caldera)","agency":"National Park Service","agency_type":"NPS","nations":["Tukudika (Mountain Shoshone)","Eastern Shoshone","Bannock","Apsáalooke (Crow)","Blackfeet","Niimíipuu (Nez Perce)"],"cultures":[],"primary_nation":"Tukudika (Mountain Shoshone)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-107.5081,44.7878]},"properties":{"slug":"bighorn-national-forest","name":"Bighorn National Forest","state":"WY","summary":"A 1.1 million-acre national forest holding the Medicine Wheel, sacred to many Plains nations and the focus of access disputes that began in 1988.","acreage":"1,115,171","geology":"~2.84 billion years (Archean) granite-gneiss core (Bighorn Batholith); ~485-444 Mya Ordovician Bighorn Dolomite","epoch":"Archean (basement) / Late Ordovician (Bighorn Dolomite)","agency":"USDA Forest Service","agency_type":"USFS","nations":["Apsáalooke (Crow)","Eastern Shoshone","Cheyenne","Arapaho","Oceti Sakowin (Sioux)"],"cultures":[],"primary_nation":"Apsáalooke (Crow)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-103.4595,43.8791]},"properties":{"slug":"mount-rushmore-national-memorial","name":"Mount Rushmore National Memorial","state":"SD","summary":"A 1,278-acre national memorial carved by Gutzon Borglum, a sculptor with documented ties to the Ku Klux Klan.","acreage":"1,278","geology":"~1,715 Mya Paleoproterozoic Harney Peak leucogranite","epoch":"Paleoproterozoic","agency":"National Park Service","agency_type":"NPS","nations":["Oceti Sakowin (Sioux)","Cheyenne","Arapaho"],"cultures":[],"primary_nation":"Oceti Sakowin (Sioux)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-103.8072,44.4197]},"properties":{"slug":"black-hills-national-forest","name":"Black Hills National Forest","state":"SD","summary":"A 1.25 million-acre national forest where the Homestake Gold Mine operated from 1876 to 2002 and discharged cyanide and arsenic-bearing tailings into its creeks.","acreage":"1,253,308","geology":"~1,715 Mya Paleoproterozoic Harney Peak granite at the core; ~2,500 Mya Precambrian schist and quartzite; encircled by Paleozoic limestone and Cretaceous shale","epoch":"Paleoproterozoic","agency":"USDA Forest Service","agency_type":"USFS","nations":["Oceti Sakowin (Sioux)","Cheyenne","Arapaho","Apsáalooke (Crow)"],"cultures":[],"primary_nation":"Oceti Sakowin (Sioux)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-102.3397,43.8554]},"properties":{"slug":"badlands-national-park","name":"Badlands National Park","state":"SD","summary":"A 242,756-acre national park of mixed grass prairie, where a bombing and gunnery range operated from 1942 to 1968 and displaced 150 to 250 Oglala Lakota families.","acreage":"242,756","geology":"~34-23 Mya Oligocene-Eocene White River Group (Chadron, Brule, Sharps Formations)","epoch":"Late Eocene to Late Oligocene","agency":"National Park Service","agency_type":"NPS","nations":["Oglala Lakota","Oceti Sakowin (Sioux)"],"cultures":[],"primary_nation":"Oglala Lakota"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-96.325,44.0133]},"properties":{"slug":"pipestone-national-monument","name":"Pipestone National Monument","state":"MN","summary":"A 301-acre national monument of tallgrass prairie and pipestone quarries, on whose grounds a federal Indian boarding school operated from 1893 to about 1953.","acreage":"301","geology":"~1,700 Mya Paleoproterozoic Sioux quartzite (catlinite/pipestone argillite interbeds)","epoch":"Paleoproterozoic","agency":"National Park Service","agency_type":"NPS","nations":["Oceti Sakowin (Sioux)","Yankton Dakota"],"cultures":[],"primary_nation":"Oceti Sakowin (Sioux)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-96.514,43.69]},"properties":{"slug":"palisades-state-park","name":"Palisades State Park","state":"SD","summary":"A 435-acre South Dakota state park on Split Rock Creek's quartzite gorge, near a quarry opened in the 1890s in the same Sioux quartzite that is sacred to Dakota quarrying traditions at Pipestone.","acreage":"435","geology":"~1,700 Mya Paleoproterozoic Sioux quartzite","epoch":"Paleoproterozoic","agency":"South Dakota Game, Fish and Parks","agency_type":"State park","nations":["Oceti Sakowin (Sioux)","Yankton Dakota","Sisseton-Wahpeton Dakota"],"cultures":[],"primary_nation":"Oceti Sakowin (Sioux)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-93.3089,43.6372]},"properties":{"slug":"myre-big-island-state-park","name":"Myre-Big Island State Park","state":"MN","summary":"A 1,578-acre Minnesota state park on Albert Lea Lake that holds a collection of Native American artifacts gathered by a local amateur archaeologist through the 1940s and not publicly displayed.","acreage":"1,578","geology":"~375 Mya Middle to Late Devonian limestone and dolomite","epoch":"Middle to Late Devonian (Givetian-Frasnian)","agency":"Minnesota DNR","agency_type":"State park","nations":["Wahpekute Dakota","Sisseton Dakota","Oceti Sakowin (Sioux)"],"cultures":[],"primary_nation":"Wahpekute Dakota"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-90.7678,42.1203]},"properties":{"slug":"maquoketa-caves-state-park","name":"Maquoketa Caves State Park","state":"IA","summary":"A 370-acre Iowa state park of caves from which Woodland-period pottery and tools were removed to collections, with no public record of NAGPRA compliance.","acreage":"370","geology":"~430 Mya Silurian dolomite (Hopkinton and Scotch Grove formations) overlying Late Ordovician Maquoketa Formation limestone and shale","epoch":"Early Silurian (Llandovery-Wenlock); Late Ordovician strata below","agency":"Iowa DNR","agency_type":"State park","nations":["Báxoje (Ioway)","Sauk","Meskwaki","Ho-Chunk","Oceti Sakowin (Sioux)"],"cultures":[],"primary_nation":"Báxoje (Ioway)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-90.159,42.1384]},"properties":{"slug":"mississippi-palisades-state-park","name":"Mississippi Palisades State Park","state":"IL","summary":"A 2,500-acre Illinois state park on unglaciated Mississippi River bluffs, seven miles south of the Savanna Army Depot, a Superfund site that operated from 1917 to 1995.","acreage":"2,500","geology":"~425 Mya Silurian dolomite","epoch":"Late Silurian (Wenlock-Ludlow)","agency":"Illinois DNR","agency_type":"State park","nations":["Ho-Chunk","Sauk","Meskwaki"],"cultures":["Hopewell"],"primary_nation":"Ho-Chunk"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-85.6201,40.0958]},"properties":{"slug":"mounds-state-park","name":"Mounds State Park","state":"IN","summary":"A 290-acre Indiana state park on an earthwork complex where a traction company ran an amusement park, roller coaster included, from 1897 to 1929.","acreage":"290","geology":"~420 Mya Silurian dolomite and limestone forming bedrock subcrop; Pleistocene Wisconsinan glacial till (Tipton Till Plain) blankets the upland surface; limestone bluffs exposed along the White River valley","epoch":"Late Silurian; Pleistocene (Wisconsinan) surficial landscape","agency":"Indiana DNR","agency_type":"State park","nations":["Lenape (Delaware)","Myaamia (Miami)"],"cultures":["Adena","Hopewell"],"primary_nation":"Lenape (Delaware)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-87.049,39.9423]},"properties":{"slug":"pine-hills-nature-preserve","name":"Pine Hills Nature Preserve","state":"IN","summary":"A 480-acre Indiana nature preserve of relict hemlock and white pine, where a sandstone ridge was notched in 1868 to carry water to a woolen mill.","acreage":"480","geology":"~310 Mya Pennsylvanian sandstone over ~340 Mya Mississippian Borden Group siltstone and limestone; junction of formations produces abundant springs throughout the preserve; marine fossils including crinoids, bryozoans, and brachiopods in Mississippian layer","epoch":"Pennsylvanian (upper); Mississippian (lower)","agency":"Indiana DNR","agency_type":"State nature preserve","nations":["Myaamia (Miami)","Wea","Potawatomi","Shawnee"],"cultures":[],"primary_nation":"Myaamia (Miami)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-86.8425,40.4973]},"properties":{"slug":"prophetstown-state-park","name":"Prophetstown State Park","state":"IN","summary":"A 2,000-acre Indiana state park of restored prairie at the Tippecanoe and Wabash confluence, where Tenskwatawa established Prophetstown in 1808.","acreage":"2,000","geology":"~375 Mya Devonian New Albany Shale and Mississippian Borden Group siltstone and crinoidal limestone forming the bedrock subcrop; landscape sculpted by Pleistocene Wabash Torrent (~14,000 BP) as glacial Lake Maumee breached the Fort Wayne moraine, depositing glacial outwash terraces above the Wabash-Tippecanoe confluence","epoch":"Late Devonian to early Mississippian (Famennian to Kinderhookian); surficial landscape Pleistocene (Wisconsinan)","agency":"Indiana DNR","agency_type":"State park","nations":["Myaamia (Miami)","Potawatomi","Shawnee","Wea","Kickapoo","Lenape (Delaware)"],"cultures":[],"primary_nation":"Myaamia (Miami)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-87.0748,39.9326]},"properties":{"slug":"shades-state-park","name":"Shades State Park","state":"IN","summary":"A 3,082-acre Indiana state park on Sugar Creek that began as The Shades, a mineral springs health resort with a 40-room inn built in 1887.","acreage":"3,082","geology":"~310 Mya Pennsylvanian sandstone over ~340 Mya Mississippian Borden Group siltstone and limestone; deep sandstone ravines carved by Sugar Creek drainage","epoch":"Pennsylvanian (upper); Mississippian (lower, Borden Group)","agency":"Indiana DNR","agency_type":"State park","nations":["Myaamia (Miami)","Wea","Shawnee","Potawatomi"],"cultures":[],"primary_nation":"Myaamia (Miami)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-83.4063,39.1131]},"properties":{"slug":"fort-hill-state-memorial","name":"Fort Hill State Memorial","state":"OH","summary":"A 1,300-acre Ohio History Connection memorial of old-growth forest around an enclosure that Squier and Davis excavated in 1846 for the Smithsonian.","acreage":"1,300","geology":"~443-323 Mya Silurian through Mississippian dolomite, shale, and sandstone; Peebles Dolomite (Silurian Wenlockian-Ludlovian) forms the plateau upland; Ohio Shale and Berea Sandstone exposed in gorge section; site on unglaciated Allegheny Plateau with natural bridge.","epoch":"Wenlockian to Mississippian.","agency":"Ohio History Connection","agency_type":"State historic site","nations":["Shawnee","Myaamia (Miami)"],"cultures":["Hopewell","Adena"],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-81.5497,41.2417]},"properties":{"slug":"cuyahoga-valley-national-park","name":"Cuyahoga Valley National Park","state":"OH","summary":"A 32,950-acre national park along the Cuyahoga River, which caught fire at least 13 documented times between 1868 and 1969.","acreage":"32,950","geology":"~360 Mya Upper Devonian shale and sandstone (Bedford Shale, Berea Sandstone, Chagrin Shale, Ohio Shale); overlain by Mississippian Cuyahoga Formation and Pennsylvanian Sharon Conglomerate; valley carved by Pleistocene glaciation with glacial drift to 400-foot depth.","epoch":"Upper Devonian (Famennian) to early Mississippian.","agency":"National Park Service","agency_type":"NPS","nations":["Erie","Wyandot","Lenape (Delaware)","Shawnee","Seneca"],"cultures":["Hopewell"],"primary_nation":"Erie"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-81.5449,41.272]},"properties":{"slug":"krejci-dump","name":"Krejci Dump, Cuyahoga Valley National Park","state":"OH","summary":"A 200-acre restored wetland in Cuyahoga Valley National Park on the site of an unregulated hazardous waste dump that took industrial waste from 1948 to 1980.","acreage":"200","geology":"~360 Mya Upper Devonian shale (Bedford Shale, Ohio Shale, Cleveland Shale); overlain by Pleistocene glacial till and clay deposits of the Wisconsinan glaciation.","epoch":"Upper Devonian (Famennian).","agency":"National Park Service","agency_type":"NPS","nations":["Wyandot","Lenape (Delaware)","Shawnee","Erie","Seneca"],"cultures":[],"primary_nation":"Wyandot"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-82.2095,39.9848]},"properties":{"slug":"flint-ridge-state-memorial","name":"Flint Ridge State Memorial","state":"OH","summary":"A 533-acre Ohio History Connection memorial on a 12,000-year-old Indigenous chert quarry landscape that settlers mined commercially for gunflints and millstones until about 1840.","acreage":"533","geology":"~320 Mya Pennsylvanian Vanport chert (Vanport Limestone Member, Allegheny Group); cryptocrystalline quartz (SiO2) formed through secondary silicification of a marine limestone by sponge-derived silica-rich fluids.","epoch":"Desmoinesian stage, Middle Pennsylvanian.","agency":"Ohio History Connection","agency_type":"State historic site","nations":["Wyandot","Lenape (Delaware)","Shawnee","Myaamia (Miami)"],"cultures":["Hopewell","Adena"],"primary_nation":"Wyandot"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-82.4278,40.0403]},"properties":{"slug":"octagon-earthworks","name":"Octagon Earthworks","state":"OH","summary":"A 70-acre Ohio History Connection site holding the Octagon Earthworks, on which a private country club ran a golf course from 1910 to 2025.","acreage":"70","geology":"~385 Mya Devonian limestone (Columbus Limestone, Delaware Limestone); earthworks constructed on Pleistocene glacial outwash terraces above the Licking River system.","epoch":"Middle to Late Devonian.","agency":"Ohio History Connection","agency_type":"State historic site","nations":["Lenape (Delaware)","Shawnee","Wyandot","Myaamia (Miami)"],"cultures":["Hopewell"],"primary_nation":"Lenape (Delaware)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-82.4301,40.0422]},"properties":{"slug":"newark-earthworks","name":"Newark Earthworks","state":"OH","summary":"A 206-acre remnant of an earthwork complex that once covered more than 4 square miles, more than 90 percent of it destroyed by canals, railroads, farming, and urban growth.","acreage":"206","geology":"~385 Mya Devonian limestone (Columbus Limestone, Delaware Limestone) and shale (Olentangy Shale, Ohio Shale); earthworks constructed on Pleistocene glacial outwash terraces above the Licking River system.","epoch":"Middle to Late Devonian.","agency":"Ohio History Connection","agency_type":"State historic site","nations":["Lenape (Delaware)","Shawnee","Wyandot","Myaamia (Miami)"],"cultures":["Hopewell"],"primary_nation":"Lenape (Delaware)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-83.1632,41.6156]},"properties":{"slug":"magee-marsh-wildlife-area","name":"Magee Marsh Wildlife Area","state":"OH","summary":"A 2,202-acre diked Lake Erie marsh, a remnant of the Great Black Swamp that was drained for farming chiefly between 1859 and 1885.","acreage":"2,202","geology":"~443 to 419 Mya Silurian dolomite: Tymochtee Dolomite (olive gray to yellowish brown, thin to massive bedded, with carbonaceous shale partings, 0 to 140 feet thick) under the marsh, with the underlying Greenfield Dolomite beneath the boardwalk woods (Ohio Geological Survey 1:24,000 bedrock map, Oak Harbor quadrangle); the bedrock is buried under Late Wisconsinan laminated lacustrine clay laid down in proglacial Lake Maumee, about 14,000 radiocarbon years (about 17,500 calendar years) ago.","epoch":"Silurian (Tymochtee and Greenfield Dolomites); surface Late Wisconsinan glacial lake clay","agency":"Ohio DNR","agency_type":"State wildlife area","nations":["Ottawa (Odawa)","Wyandot","Potawatomi","Erie"],"cultures":[],"primary_nation":"Ottawa (Odawa)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-83.8518,41.5545]},"properties":{"slug":"oak-openings-metropark","name":"Oak Openings Metropark","state":"OH","summary":"A 5,000-acre Toledo metropark of globally rare oak savanna, an ecosystem reduced from about 130 square miles to fewer than 300 high-quality remnant acres.","acreage":"5,000","geology":"~390 Mya Middle Devonian dolomite and limestone (Lucas Dolomite, Silica Formation) buried beneath Pleistocene glacial drift; surface dominated by glacial outwash sand deposited from glacial Lake Warren (~13,000 ya) and aeolian dune formation 13,000-8,000 ya.","epoch":"Middle Devonian; surface Pleistocene (Late Wisconsinan).","agency":"Metroparks Toledo","agency_type":"County park","nations":["Wyandot","Ottawa (Odawa)","Potawatomi","Shawnee","Myaamia (Miami)","Kaskaskia","Kickapoo"],"cultures":[],"primary_nation":"Wyandot"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-83.3412,41.8977]},"properties":{"slug":"ford-marsh-unit","name":"Ford Marsh Unit, Detroit River International Wildlife Refuge","state":"MI","summary":"A 485-acre coastal marsh unit of the Detroit River International Wildlife Refuge at the mouth of the River Raisin, site of the 1813 Battle of Frenchtown, the worst American defeat of the War of 1812.","acreage":"485","geology":"~385 Mya Middle Devonian dolomite and limestone (Detroit River Group); bedrock overlain by Pleistocene Wisconsin glacial clay, silt, and lacustrine deposits; site occupies the western Lake Erie lake plain at the mouth of the River Raisin.","epoch":"Middle Devonian (Eifelian).","agency":"U.S. Fish and Wildlife Service","agency_type":"USFWS","nations":["Ottawa (Odawa)","Potawatomi","Wyandot","Ojibwe"],"cultures":[],"primary_nation":"Ottawa (Odawa)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-83.3335,41.9156]},"properties":{"slug":"william-c-sterling-state-park","name":"William C. Sterling State Park","state":"MI","summary":"A 1,300-acre Michigan state park of Lake Erie marsh and beach, about two miles north of the coal-fired Monroe Power Plant, which draws about 600 million gallons of lake water a day.","acreage":"1,300","geology":"~385 Mya Middle Devonian dolomite and limestone (Detroit River Group); bedrock overlain by Pleistocene Wisconsin glacial clay, silt, and sand deposits.","epoch":"Middle Devonian (Eifelian).","agency":"Michigan DNR","agency_type":"State park","nations":["Ottawa (Odawa)","Potawatomi","Wyandot","Ojibwe"],"cultures":[],"primary_nation":"Ottawa (Odawa)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-83.315,40.7158]},"properties":{"slug":"killdeer-plains-wildlife-area","name":"Killdeer Plains Wildlife Area","state":"OH","summary":"A 9,054-acre Ohio wildlife area on the former Sandusky Plains wet prairie, in country where a Wyandot reserve set aside in 1817 was extinguished and the nation forcibly removed in July 1843.","acreage":"9,054","geology":"~390 Mya Middle Devonian limestone (Columbus Limestone); bedrock overlain by Pleistocene glacial till and outwash from the Wisconsin glaciation.","epoch":"Middle Devonian (Eifelian/Givetian); surface Pleistocene (Wisconsinan).","agency":"Ohio DNR","agency_type":"State wildlife area","nations":["Wyandot","Shawnee","Lenape (Delaware)"],"cultures":[],"primary_nation":"Wyandot"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-83.198,42.0117]},"properties":{"slug":"pointe-mouillee-state-game-area","name":"Pointe Mouillee State Game Area","state":"MI","summary":"A 4,040-acre Michigan state game area of restored Lake Erie marsh beside a 700-acre Army Corps dike that holds contaminated dredge spoil from the Detroit and Rouge Rivers.","acreage":"4,040","geology":"~375 Mya Late Devonian shale and carbonate (Famennian); bedrock overlain by Pleistocene Wisconsin glacial and lacustrine deposits; site occupies the Lake Erie lake plain formed by the drainage of glacial Lake Maumee ~14,500 ya.","epoch":"Late Devonian (Famennian).","agency":"Michigan DNR","agency_type":"State game area","nations":["Ottawa (Odawa)","Potawatomi","Wyandot","Ojibwe"],"cultures":[],"primary_nation":"Ottawa (Odawa)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-83.384,38.7924]},"properties":{"slug":"edge-of-appalachia","name":"Edge of Appalachia Preserve","state":"OH","summary":"A 21,000-acre preserve of forest, limestone prairie, and cedar barrens in the Ohio Brush Creek basin, which also holds the closed Killen Generating Station and its unlined coal ash ponds.","acreage":"21,000","geology":"~430 Mya Silurian dolomite (Peebles Dolomite, Wenlockian stage); underlying Ordovician shale and limestone exposed in stream valley bottoms","epoch":"Middle Silurian (Wenlockian)","agency":"The Nature Conservancy / Cincinnati Museum Center","agency_type":"Private preserve","nations":["Shawnee","Myaamia (Miami)"],"cultures":["Adena","Hopewell","Fort Ancient culture"],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-84.3708,39.0343]},"properties":{"slug":"st-annes-woods-and-wetlands","name":"St. Anne's Woods and Wetlands","state":"KY","summary":"A 165-acre Kentucky preserve of old-growth beech forest and Ohio River floodplain wetland, donated in 1909 to the Sisters of Divine Providence, with its earlier ownership undocumented in public records.","acreage":"165","geology":"~450 Mya Upper Ordovician shale and fossiliferous limestone (Kope Formation, Cincinnatian Series); Ohio River alluvium at site","epoch":"Late Ordovician (Cincinnatian)","agency":"Campbell County Conservation District","agency_type":"Conservation district","nations":["Shawnee"],"cultures":["Adena","Hopewell","Fort Ancient culture"],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-83.6078,37.8339]},"properties":{"slug":"red-river-gorge-geological-area","name":"Red River Gorge Geological Area","state":"KY","summary":"A 29,000-acre geological area in the Daniel Boone National Forest, where a dam Congress authorized in 1962 would have flooded two-thirds of the gorge.","acreage":"29,000","geology":"~310 Mya Pennsylvanian Corbin Sandstone (Grundy Formation, Pottsville Escarpment); deposited in marine and deltaic river delta environments beginning ~340 Mya; prominent iron-oxide Liesegang banding; over 100 natural sandstone arches, highest concentration east of the Mississippi River.","epoch":"Early Pennsylvanian (Morrowan).","agency":"USDA Forest Service (Daniel Boone National Forest)","agency_type":"USFS","nations":["Cherokee","Shawnee"],"cultures":["Paleoindian","Adena"],"primary_nation":"Cherokee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-83.2214,39.2417]},"properties":{"slug":"seip-earthworks","name":"Seip Earthworks","state":"OH","summary":"A 121-acre National Park Service earthwork site where Ohio Historical Society excavations beginning in 1906 removed burials and their copper, mica, shell, and pearl objects to Columbus.","acreage":"121","geology":"~425 Mya Silurian dolomite (Peebles Dolomite, Tymochtee Dolomite); earthworks constructed on Pleistocene glacial outwash terrace above Paint Creek at the maximum extent of both the Illinoian and Wisconsinan glacial advances.","epoch":"Late Silurian (Ludlovian).","agency":"National Park Service","agency_type":"NPS","nations":["Shawnee","Myaamia (Miami)"],"cultures":["Adena","Hopewell"],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-83.472,39.1861]},"properties":{"slug":"rocky-fork-state-park","name":"Rocky Fork State Park","state":"OH","summary":"A 3,464-acre Ohio state park around Rocky Fork Lake, impounded from 1951 to 1953 by flooding creek bottomland and condemning valley farms.","acreage":"3,464","geology":"~425 Mya Silurian dolomite (Peebles Dolomite, Ludlovian); 75-ft gorge incised during and after the Wisconsinan glaciation, roughly 20,000 to 12,000 years ago, when glacier ice blocked Rocky Fork Creek's original drainage outlet, reversing stream flow direction and rapidly cutting through dolomite bedrock; carbonate dissolution formed cave systems in the gorge walls; collapsed cave ceilings visible as large slump blocks in the streambed.","epoch":"Middle Silurian (Wenlockian/Ludlovian).","agency":"Ohio DNR","agency_type":"State park","nations":["Shawnee","Myaamia (Miami)"],"cultures":["Hopewell"],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-83.0064,39.3758]},"properties":{"slug":"hopewell-culture-national-historical-park","name":"Hopewell Culture National Historical Park","state":"OH","summary":"A 1,170-acre national historical park of Hopewell earthworks on the Scioto River, where in 1846 Squier and Davis took about 200 effigy pipes from Mound City, most now in the British Museum.","acreage":"1,170","geology":"~375 Mya Devonian shale (Ohio Shale, Olentangy Shale); earthworks built on Pleistocene glacial outwash terraces.","epoch":"Late Devonian.","agency":"National Park Service","agency_type":"NPS","nations":["Shawnee","Myaamia (Miami)"],"cultures":["Adena","Hopewell"],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-81.0758,38.07]},"properties":{"slug":"new-river-gorge-national-park","name":"New River Gorge National Park and Preserve","state":"WV","summary":"A 72,808-acre national park and preserve in a gorge whose coal company towns paid miners in scrip and kept them behind armed guards.","acreage":"72,808","geology":"~325 Mya Pennsylvanian and Mississippian sandstone, shale, and coal seams.","epoch":"Pennsylvanian (Carboniferous).","agency":"National Park Service","agency_type":"NPS","nations":["Shawnee","Cherokee","Seneca","Moneton"],"cultures":[],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-84.7474,38.8838]},"properties":{"slug":"big-bone-lick","name":"Big Bone Lick State Historic Site","state":"KY","summary":"A 525-acre Kentucky state historic site at a sulphur spring stripped of fossil bones for nearly 300 years, beginning with a French collection shipped to Paris in 1739.","acreage":"525","geology":"~450 Mya Ordovician limestone and shale (Kope Formation); Pleistocene fossil-bearing bog deposits (25,000-12,000 BP).","epoch":"Late Ordovician (Cincinnatian Series); late Pleistocene (Wisconsinan Glaciation).","agency":"Kentucky State Parks","agency_type":"State historic site","nations":["Shawnee","Lenape (Delaware)"],"cultures":["Paleoindian"],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-84.8153,38.9989]},"properties":{"slug":"dinsmore-woods","name":"Dinsmore Woods State Nature Preserve","state":"KY","summary":"A 107-acre old-growth forest preserve, the wooded part of the Dinsmore farm, a plantation where enslaved people lived and labored from 1842.","acreage":"107","geology":"~450 Mya Ordovician limestone and shale.","epoch":"Late Ordovician (Cincinnatian Series); Kope, Fairview, and Bull Fork formations.","agency":"Boone County Parks / Office of Kentucky Nature Preserves","agency_type":"State nature preserve","nations":["Shawnee","Cherokee"],"cultures":["Adena"],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-84.0365,39.5146]},"properties":{"slug":"caesar-creek","name":"Caesar Creek State Park","state":"OH","summary":"A 7,530-acre Ohio state park around a Corps of Engineers lake whose creation flooded the village of New Burlington and displaced about 300 residents.","acreage":"7,530","geology":"~447 Mya Ordovician limestone and shale.","epoch":"Late Ordovician (Cincinnatian Series); Waynesville, Liberty, and Whitewater formations.","agency":"Ohio DNR","agency_type":"State park","nations":["Shawnee","Myaamia (Miami)"],"cultures":["Hopewell","Fort Ancient culture"],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-84.8084,39.1207]},"properties":{"slug":"shawnee-lookout","name":"Shawnee Lookout","state":"OH","summary":"A 2,179-acre Hamilton County park above the Ohio and Great Miami confluence, an archaeological district whose 1974 National Register listing did not prevent later construction by the park district.","acreage":"2,179","geology":"~450 Mya Ordovician limestone and shale.","epoch":"Late Ordovician (Cincinnatian Series); Waynesville and Arnheim formations.","agency":"Great Parks of Hamilton County","agency_type":"County park","nations":["Shawnee","Myaamia (Miami)"],"cultures":["Adena","Hopewell","Fort Ancient culture"],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-84.6878,39.2922]},"properties":{"slug":"fernald-preserve","name":"Fernald Preserve","state":"OH","summary":"A 1,050-acre preserve of restored prairie and wetland on the site of the Fernald Feed Materials Production Center, which refined uranium metal for nuclear weapons from 1951 to 1989.","acreage":"1,050","geology":"~450 Mya Ordovician limestone and shale.","epoch":"Late Ordovician (Cincinnatian Series).","agency":"U.S. Department of Energy, Office of Legacy Management","agency_type":"DOE legacy site","nations":["Myaamia (Miami)","Shawnee"],"cultures":["Fort Ancient culture"],"primary_nation":"Myaamia (Miami)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-85.4188,38.7608]},"properties":{"slug":"clifty-falls-state-park","name":"Clifty Falls State Park","state":"IN","summary":"A 1,416-acre Indiana state park of canyon forest beside the former Madison State Hospital, whose psychiatric patients farmed the adjacent fields without pay.","acreage":"1,416","geology":"~445 Mya Ordovician limestone and shale.","epoch":"Late Ordovician; Dillsboro Formation (shale and limestone) on lower canyon slopes; Saluda Formation (limestone and dolomite) capping waterfall crests and upper cliffs.","agency":"Indiana DNR","agency_type":"State park","nations":["Shawnee","Myaamia (Miami)"],"cultures":[],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-84.4233,39.1991]},"properties":{"slug":"french-park","name":"French Park","state":"OH","summary":"A 275-acre Cincinnati park holding the Benham Mound, a Hopewell burial mound dug by local residents in the late 19th century, with no known repository for what they took.","acreage":"275","geology":"~450 Mya Ordovician limestone and shale.","epoch":"Late Ordovician (Cincinnatian Series).","agency":"Cincinnati Parks","agency_type":"Municipal park","nations":["Shawnee","Myaamia (Miami)"],"cultures":["Adena","Hopewell"],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-84.7025,36.5072]},"properties":{"slug":"big-south-fork-national-river-and-recreation-area","name":"Big South Fork National River and Recreation Area","state":"TN","summary":"A 125,000-acre national river and recreation area where abandoned coal mines still drain acid into its creeks.","acreage":"125,000","geology":"~310 Mya Pennsylvanian sandstone and conglomerate.","epoch":"Pennsylvanian.","agency":"National Park Service","agency_type":"NPS","nations":["Cherokee","Yuchi","Shawnee"],"cultures":[],"primary_nation":"Cherokee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-86.1,37.1877]},"properties":{"slug":"mammoth-cave-national-park","name":"Mammoth Cave National Park","state":"KY","summary":"A 54,012-acre national park where in 1842 enslaved workers built huts inside the cave for a tuberculosis hospital in which five patients died.","acreage":"54,012 acres","geology":"~340 million years ago (limestone bedrock); cave passages formed over last 10 million years.","epoch":"Mississippian period; St. Louis and Ste. Genevieve limestone formations; karst dissolution ongoing since Pliocene.","agency":"National Park Service","agency_type":"NPS","nations":["Shawnee","Cherokee","Chickasaw","Osage","Yuchi"],"cultures":[],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-93.9308,29.6776]},"properties":{"slug":"sea-rim-state-park","name":"Sea Rim State Park","state":"TX","summary":"A 4,141-acre Texas state park of Gulf beach and tidal marsh, bought in 1972 from an oil company, with active rigs still visible from the beach.","acreage":"4,141 acres","geology":"~11,700 years ago - present.","epoch":"Holocene (Meghalayan age); Quaternary period.","agency":"Texas Parks and Wildlife","agency_type":"State park","nations":["Ishak (Atakapa-Ishak)","Akokisa"],"cultures":[],"primary_nation":"Ishak (Atakapa-Ishak)"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-101.0578,33.9778]},"properties":{"slug":"caprock-canyon","name":"Caprock Canyons State Park","state":"TX","summary":"A 15,313-acre Texas state park, home of the Texas State Bison Herd, descended from calves captured beginning in 1878 after the extermination campaign of 1874 to 1878.","acreage":"15,313 acres","geology":"~299-2.6 million years ago (surface strata).","epoch":"Permian through Pliocene; Quartermaster Formation (Permian, ~280 Mya); caliche caprock (Pliocene, ~5 Mya).","agency":"Texas Parks and Wildlife","agency_type":"State park","nations":["Comanche","Kiowa","Apache"],"cultures":[],"primary_nation":"Comanche"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-101.6713,34.8873]},"properties":{"slug":"palo-duro-canyon","name":"Palo Duro Canyon State Park","state":"TX","summary":"A 29,182-acre Texas state park built in part by two Civilian Conservation Corps companies of African American enrollees who arrived in August 1935.","acreage":"29,182 acres","geology":"~252-201 million years ago (exposed strata).","epoch":"Triassic (Carnian-Norian); Tecovas Formation (~225 Mya) and Trujillo Formation (~218 Mya); canyon incision began Pliocene (~5 Mya).","agency":"Texas Parks and Wildlife","agency_type":"State park","nations":["Comanche","Kiowa","Southern Cheyenne","Arapaho"],"cultures":[],"primary_nation":"Comanche"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-90.848,37.553]},"properties":{"slug":"johnsons-shut-ins-state-park","name":"Johnson's Shut-Ins State Park","state":"MO","summary":"An 8,916-acre Missouri state park in the Ozark Highland, assembled over 17 years by a lead-mining heir and donated to the state in 1955.","acreage":"8,916 acres","geology":"~1.47 billion years ago (bedrock).","epoch":"Proterozoic eon; Mesoproterozoic era, Calymmian period; St. Francois Mountains rhyolite and granite among the oldest exposed rock in Missouri; river incision Quaternary.","agency":"Missouri State Parks","agency_type":"State park","nations":["Osage"],"cultures":["Paleoindian"],"primary_nation":"Osage"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-90.726,37.637]},"properties":{"slug":"elephant-rocks-state-park","name":"Elephant Rocks State Park","state":"MO","summary":"A 132-acre Missouri state park of granite outcrops beside the Graniteville quarry, a company town from 1869 that supplied granite for the Eads Bridge piers and St. Louis streets.","acreage":"132 acres","geology":"~1.47 billion years ago (granite intrusion).","epoch":"Proterozoic eon; Mesoproterozoic era, Calymmian period; Graniteville Granite pluton emplaced during the 1.48 to 1.45 Ga anorogenic magmatism of the Eastern Granite-Rhyolite Province on the southern Laurentian margin; spheroidal weathering forms developed over millions of subsequent years.","agency":"Missouri State Parks","agency_type":"State park","nations":["Osage"],"cultures":[],"primary_nation":"Osage"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-98.688,34.726]},"properties":{"slug":"charons-garden-wilderness-area","name":"Charon's Garden Wilderness Area","state":"OK","summary":"A 5,723-acre wilderness of granite and prairie in the Wichita Mountains, the core of Comancheria until the Comanche were confined to a reservation after the Red River War of 1874 to 1875.","acreage":"5,723 acres","geology":"~525 million years ago (bedrock).","epoch":"Cambrian period; Furongian epoch; among the oldest exposed rock in the southern Great Plains; basement exhumed through erosion of overlying Paleozoic and Mesozoic cover.","agency":"U.S. Fish and Wildlife Service","agency_type":"USFWS","nations":["Comanche","Kiowa","Wichita","Apache"],"cultures":[],"primary_nation":"Comanche"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-98.673,34.769]},"properties":{"slug":"wichita-mountains-national-wildlife-refuge","name":"Wichita Mountains National Wildlife Refuge","state":"OK","summary":"A 59,020-acre refuge with a bison herd reintroduced in 1907, on land ceded by the Kiowa, Comanche, and Apache under the Jerome Agreement over sustained Kiowa opposition.","acreage":"59,020 acres","geology":"~525 million years ago (bedrock); mountains re-exhumed ~300 Mya.","epoch":"Cambrian bedrock (Furongian); Wichita Mountains uplifted during Pennsylvanian Ouachita Orogeny (~300 Mya), then buried and re-exhumed; one of the most geologically complex mountain histories in the U.S.","agency":"U.S. Fish and Wildlife Service","agency_type":"USFWS","nations":["Comanche","Kiowa","Wichita","Apache"],"cultures":[],"primary_nation":"Comanche"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-83.831,39.796]},"properties":{"slug":"john-bryan-state-park","name":"John Bryan State Park","state":"OH","summary":"A 752-acre Ohio state park on the Little Miami River gorge, a corridor that ran at least six mills within one mile by the early 19th century.","acreage":"752 acres (park); 268 acres (Clifton Gorge SNP)","geology":"~430-420 million years ago (bedrock); gorge carved ~12,000-14,000 years ago.","epoch":"Silurian period (Llandovery-Wenlock); dolomite formed in shallow tropical sea; gorge incised during Late Pleistocene and early Holocene by glacial meltwater drainage.","agency":"Ohio DNR","agency_type":"State park","nations":["Shawnee","Myaamia (Miami)"],"cultures":["Adena","Hopewell"],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-82.5408,39.4354]},"properties":{"slug":"hocking-hills","name":"Hocking Hills State Park","state":"OH","summary":"A 2,356-acre Ohio state park of hemlock gorges and rock shelters whose infrastructure was built in the 1930s by two racially segregated Civilian Conservation Corps companies.","acreage":"2,356 acres (park); adjacent 9,267-acre Hocking State Forest","geology":"~330 million years ago (sandstone); caves and gorges carved ~14,000-18,000 years ago.","epoch":"Mississippian period (Osagean-Meramecian); Black Hand sandstone deposited in deltaic system; recess caves and gorges formed by Pleistocene periglacial weathering and glacial meltwater during Wisconsin glaciation.","agency":"Ohio DNR","agency_type":"State park","nations":["Shawnee","Lenape (Delaware)","Wyandot"],"cultures":["Adena","Hopewell"],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-83.54,38.82]},"properties":{"slug":"arc-of-appalachia","name":"Arc of Appalachia","state":"OH","summary":"A 15,677-acre Ohio preserve system, among the state's most biodiverse landscapes, whose record includes Putnam's excavation of Serpent Mound from 1887 to 1889.","acreage":"15,677 acres across preserve system","geology":"~485-420 million years ago (bedrock).","epoch":"Ordovician and Silurian periods; limestone and dolomite deposited in shallow Iapetus Ocean; terrain never covered by Pleistocene glaciation; landscape continuity extending back millions of years.","agency":"Arc of Appalachia Preserve System","agency_type":"Private preserve","nations":["Shawnee"],"cultures":["Adena","Hopewell"],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-84.587,39.168]},"properties":{"slug":"mount-airy-forest","name":"Mount Airy Forest","state":"OH","summary":"A 1,459-acre reforested Cincinnati park built in part by an all-Black Civilian Conservation Corps company that arrived in May 1935.","acreage":"1,459 acres","geology":"~450 million years ago (Ordovician bedrock); surface soils entirely reworked by 19th-century agricultural erosion and 20th-century reforestation.","epoch":"Ordovician period (Cincinnatian); overlain by Wisconsin glacial till; original forest cleared by 1900 through farming and grazing; reforestation begun 1911; one of the first municipal reforestation projects in the United States.","agency":"Cincinnati Parks","agency_type":"Municipal park","nations":["Shawnee"],"cultures":["Fort Ancient culture"],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-83.8328,39.7993]},"properties":{"slug":"clifton-gorge-state-nature-preserve","name":"Clifton Gorge State Nature Preserve","state":"OH","summary":"A 268-acre Ohio nature preserve in a gorge of the Little Miami River, where six mills operated within one mile by the early 19th century.","acreage":"268 acres","geology":"~445-430 million years ago (bedrock); gorge carved ~15,000 years ago.","epoch":"Silurian period (Llandovery-Wenlock); Cedarville Dolomite, Springfield Dolomite, and interbedded shale; gorge cut by Wisconsin glacial meltwater; National Natural Landmark 1967.","agency":"Ohio DNR","agency_type":"State nature preserve","nations":["Shawnee","Myaamia (Miami)"],"cultures":["Adena","Hopewell"],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-84.5348,39.1709]},"properties":{"slug":"parker-woods","name":"Parker Woods","state":"OH","summary":"A roughly 63-acre Cincinnati park of mature forest beside the Mill Creek watershed, which a 1996 assessment found to hold three Superfund sites and 31 other hazardous waste sites.","acreage":"~63 acres","geology":"~450 Mya Ordovician shale and limestone (Kope Formation).","epoch":"Late Ordovician (Cincinnatian Series).","agency":"Cincinnati Parks","agency_type":"Municipal park","nations":["Shawnee","Myaamia (Miami)"],"cultures":["Adena","Hopewell"],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-83.891,39.803]},"properties":{"slug":"glen-helen-nature-preserve","name":"Glen Helen Nature Preserve","state":"OH","summary":"A 1,000-acre preserve of old-growth gorge forest where an unregulated dig into the Orators Mound in 1953 and 1954 found five skeletons and left no report.","acreage":"1,000 acres","geology":"~445-430 million years ago (bedrock); gorge and ravine system formed by glacial meltwater ~15,000 years ago.","epoch":"Silurian period (Llandovery-Wenlock); same dolomite and limestone formations as Clifton Gorge; Holocene iron precipitation at Yellow Spring actively ongoing; visible as orange mineral staining on rock surfaces.","agency":"Glen Helen Association","agency_type":"Private preserve","nations":["Shawnee","Myaamia (Miami)"],"cultures":["Adena"],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-84.428,39.102]},"properties":{"slug":"otto-armleder-memorial-park","name":"Otto Armleder Memorial Park","state":"OH","summary":"A 347-acre Cincinnati park on the Little Miami floodplain, downstream of an industrial corridor whose streambed sediments carry insecticides and PCBs.","acreage":"347 acres","geology":"~450 million years ago (Ordovician bedrock); floodplain deposits Holocene.","epoch":"Ordovician period (Cincinnatian); overlain by Quaternary glacial outwash and Holocene alluvium; site lies on Little Miami River floodplain shaped by Wisconsin glaciation meltwater.","agency":"Cincinnati Parks","agency_type":"Municipal park","nations":["Shawnee"],"cultures":["Fort Ancient culture"],"primary_nation":"Shawnee"}},{"type":"Feature","geometry":{"type":"Point","coordinates":[-84.62,39.11]},"properties":{"slug":"bender-mountain-nature-preserve","name":"Bender Mountain Nature Preserve","state":"OH","summary":"A 130-acre Cincinnati preserve on a steep Ohio River bluff with more than 390 plant species, on land formerly grazed, farmed, and selectively logged.","acreage":"130+ acres","geology":"~450 million years ago (Ordovician bedrock); ridge morphology shaped by the pre-Illinoian glaciation that established the Ohio River here roughly 730,000 to 900,000 years ago.","epoch":"Ordovician period (Cincinnatian); the modern Ohio River was created when pre-Illinoian ice dammed the west-flowing Teays River and formed glacial Lake Tight, whose overflow cut this valley and left oversteepened walls; Pleistocene colluvium mantles bedrock slopes.","agency":"Cincinnati Parks","agency_type":"Municipal park","nations":["Shawnee"],"cultures":["Adena","Hopewell"],"primary_nation":"Shawnee"}}]};
